CREATE TABLE IF NOT EXISTS fin_supplier_payments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, bill_id INT UNSIGNED NOT NULL, branch_id INT UNSIGNED NOT NULL, payment_ref VARCHAR(80) NOT NULL UNIQUE, payment_date DATE NOT NULL, account_id INT UNSIGNED NOT NULL, amount DECIMAL(18,2) NOT NULL, status ENUM('POSTED','REVERSED') NOT NULL DEFAULT 'POSTED', note VARCHAR(255) NULL, created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_fsp_bill FOREIGN KEY(bill_id) REFERENCES fin_supplier_bills(id) ON DELETE RESTRICT, CONSTRAINT fk_fsp_branch FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE RESTRICT, CONSTRAINT fk_fsp_account FOREIGN KEY(account_id) REFERENCES fin_accounts(id) ON DELETE RESTRICT);
